-- アセスメントのまとめる項目（form_kinds.topics）に、何をまとめるかの説明（guide）を入れる（docs/再設計/17_録音からの書き込み.md）。
-- 説明は、要約する AI と欄を選ぶ AI への手がかり。令和5年10月16日の課題分析標準項目の改正の通知の「項目の主な内容」をもとに、自分の言葉で短く書いた。
-- id・名前・順・by・last・keys は 0003 のまま。説明が空だと、要約が受付の方法・相談者・性別などを落とした（2026-11-20、演習シナリオ）。
UPDATE form_kinds SET topics = $json$[
  {"id": "basic", "name": "基本情報（受付、利用者等基本情報）", "guide": "相談を受けた日・方法（訪問・電話・来所など）・経路（誰の紹介か）と、相談した人（氏名・本人との続柄・性別）。利用者の氏名・性別・生年月日・年齢・住所・電話。緊急連絡先。計画を作るのが初めてかどうか", "by": "ai", "last": false},
  {"id": "history", "name": "これまでの生活と現在の状況", "guide": "これまでの暮らし（仕事・家庭での役割・趣味・付き合い）と、今の暮らしに至った経過（発症・入院・転院などの出来事と時期）", "by": "ai", "last": false},
  {"id": "socialSecurity", "name": "利用者の社会保障制度の利用情報", "guide": "介護保険・医療保険の種類、利用者負担の割合・段階、年金の種類、生活保護、障害者手帳、そのほかの制度の利用", "by": "ai", "last": false},
  {"id": "support", "name": "現在利用している支援や社会資源の状況", "guide": "今使っている介護保険のサービス・医療・障害福祉のサービス・自治体のサービス、家族以外の手助け（近所・ボランティアなど）、入院・入所している病院や施設", "by": "ai", "last": false},
  {"id": "independencePhysical", "name": "日常生活自立度（障害）", "guide": "障害高齢者の日常生活自立度（寝たきり度）。認定調査票・主治医意見書での判定と、ケアマネから見た今の自立度", "by": "ai", "last": false},
  {"id": "independenceDementia", "name": "日常生活自立度（認知症）", "guide": "認知症高齢者の日常生活自立度。認定調査票・主治医意見書での判定と、ケアマネから見た今の自立度", "by": "ai", "last": false},
  {"id": "wishes", "name": "主訴・意向", "guide": "本人の困りごと・望む暮らし・意向と、家族の困りごと・要望。誰の言葉か分かるように", "by": "ai", "last": false},
  {"id": "certification", "name": "認定情報", "guide": "要介護度（見込みを含む）、認定の状況（申請中・認定済など）、有効期間、審査会の意見、支給限度額", "by": "ai", "last": false},
  {"id": "reason", "name": "今回のアセスメントの理由", "guide": "今回アセスメントをする理由（初回、更新、区分変更、退院・退所、サービスの変更、暮らしの変化など）", "by": "ai", "last": false},
  {"id": "health", "name": "健康状態", "guide": "病名・既往歴・発症の時期と経過、症状・痛み・麻痺、身長・体重・血圧、床ずれ、受診先・かかりつけ医・受診の頻度と同行、薬と飲み方・管理、医師の指示や注意（食事・水分・服薬）、本人の健康への意識", "by": "ai", "last": false},
  {"id": "adl", "name": "ADL", "guide": "寝返り・起き上がり・座位・立ち上がり・移乗・移動（杖・車いすなど）・歩行・階段、食事・整容・更衣・入浴・トイレの動作。それぞれ自分でできるか、どんな手助けや道具が要るか、今いる場所（病院など）での様子と家での見込み", "by": "ai", "last": false},
  {"id": "iadl", "name": "IADL", "guide": "調理・掃除・洗濯・買い物・服薬の管理・お金の管理・電話・外出（交通機関・車）。誰がしているか、これから誰がするか", "by": "ai", "last": false},
  {"id": "cognition", "name": "認知機能や判断能力", "guide": "物忘れ・判断の力・自分で決める力、認知症の診断と症状（せん妄、行動・心理症状を含む）、見られる場面と頻度", "by": "ai", "last": false},
  {"id": "communication", "name": "コミュニケーションにおける理解と表出の状況", "guide": "視力・聴力、話す力と聞いて分かる力（言語障害など）、意思疎通の工夫、電話などの道具", "by": "ai", "last": false},
  {"id": "rhythm", "name": "生活リズム", "guide": "1 日と 1 週間の過ごし方（起きる・寝る・食事・活動の時間）、1 日のスケジュール、活動の量、睡眠（夜中に起きる、昼夜逆転など）", "by": "ai", "last": false},
  {"id": "excretion", "name": "排泄の状況", "guide": "排泄の場所と方法（トイレ・ポータブルトイレ・おむつなど）、尿意・便意、失禁、回数（日中・夜間）、便秘・下痢・薬、後始末、手助けと見守り", "by": "ai", "last": false},
  {"id": "hygiene", "name": "清潔の保持に関する状況", "guide": "入浴（方法・回数・手助け・道具）と整容（洗面・歯みがき・爪切り・ひげそり）、皮膚と爪の状態（床ずれを含む）、衣類や寝具の清潔", "by": "ai", "last": false},
  {"id": "oral", "name": "口腔内の状況", "guide": "歯（本数・欠け）、入れ歯、かみ合わせ、口の中（汚れ・乾き・残りかす・傷）、歯みがき・うがいの様子", "by": "ai", "last": false},
  {"id": "eating", "name": "食事摂取の状況", "guide": "食事の形（常食・刻みなど）・回数・量・内容、水分の量、栄養の状態、かむ・飲み込む様子（むせ）、食事の制限（塩分など）、食事の用意をする人、食べ方と手助け", "by": "ai", "last": false},
  {"id": "social", "name": "社会との関わり", "guide": "家庭での役割、家族や親戚・友人との付き合い、地域の活動や集まり、仕事、人に会うことへの気持ち", "by": "ai", "last": false},
  {"id": "family", "name": "家族等の状況", "guide": "家族の一人ひとり（続柄・氏名・性別・年代・同居か・仕事・健康）、主に介護する人、家族の手助けの分担と思い・負担、家族の事情", "by": "ai", "last": false},
  {"id": "housing", "name": "居住環境", "guide": "家の造り（戸建て・集合住宅・階）、段差・手すり・改修の要否、浴室・トイレ・寝る場所・食べる場所、家の中の動き方、危ない場所、家の周りの環境", "by": "ai", "last": false},
  {"id": "other", "name": "その他留意すべき事項・状況", "guide": "虐待、お金の困りごと、身寄りがない、医療への依存が高い、看取りなど、特に気をつけること", "by": "ai", "last": false},
  {"id": "overall", "name": "全体のまとめ", "guide": "今後の方針として本人・家族と話し合ったこと、これからの暮らしの見通し（誰と住み、誰が介護を担うか）", "by": "ai", "last": true},
  {"id": "date", "name": "その日の日付", "guide": "", "by": "machine", "last": false, "keys": {"first": "assessment.initialDate", "later": "assessment.updateDate"}}
]$json$::jsonb
WHERE key = 'assessment';
